style.css:
body {
  background-image: url('https://i.imgur.com/GKme3Ga.jpeg');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: 0 0;
  animation: moveBg 10s linear infinite;
}

@keyframes moveBg {
  from {
    background-position: 0 0;
  }
  to {
    background-position: 0 100%;
  }
}
